BEGIN;

-- 其他分表通过 LIKE ... INCLUDING ALL 复制此表的字段注释。
CREATE TABLE t_group_0 (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "gid" varchar(32),
    "name" varchar(64),
    "username" varchar(256),
    "sort_order" integer,
    "create_time" timestamptz,
    "update_time" timestamptz,
    "del_flag" smallint
);

COMMENT ON COLUMN t_group_0."id" IS 'ID';
COMMENT ON COLUMN t_group_0."gid" IS '分组标识';
COMMENT ON COLUMN t_group_0."name" IS '分组名称';
COMMENT ON COLUMN t_group_0."username" IS '创建分组用户名';
COMMENT ON COLUMN t_group_0."sort_order" IS '分组排序';
COMMENT ON COLUMN t_group_0."create_time" IS '创建时间';
COMMENT ON COLUMN t_group_0."update_time" IS '修改时间';
COMMENT ON COLUMN t_group_0."del_flag" IS '删除标识 0：未删除 1：已删除';

CREATE INDEX t_group_0_idx_username ON t_group_0 ("username");

CREATE TABLE t_group_unique (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "gid" varchar(32) UNIQUE
);

COMMENT ON COLUMN t_group_unique."id" IS 'ID';
COMMENT ON COLUMN t_group_unique."gid" IS '分组标识';

-- 其他分表通过 LIKE ... INCLUDING ALL 复制此表的字段注释。
CREATE TABLE t_link_0 (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "domain" varchar(128),
    -- COLLATE "C" 指定这一列按字节来比较和排序字符串,不做任何语言规则处理。
    "short_uri" varchar(8) COLLATE "C",
    "full_short_url" varchar(128),
    "origin_url" varchar(1024),
    "click_num" integer DEFAULT 0,
    "gid" varchar(32) DEFAULT 'default',
    "favicon" varchar(256),
    "enable_status" smallint,
    "created_type" smallint,
    "valid_date_type" smallint,
    "valid_date" timestamptz,
    "describe" varchar(1024),
    "total_pv" integer,
    "total_uv" integer,
    "total_uip" integer,
    "create_time" timestamptz,
    "update_time" timestamptz,
    "del_time" bigint DEFAULT 0,
    "del_flag" smallint,
    UNIQUE ("full_short_url", "del_time")
);

COMMENT ON COLUMN t_link_0."id" IS 'ID';
COMMENT ON COLUMN t_link_0."domain" IS '域名';
COMMENT ON COLUMN t_link_0."short_uri" IS '短链接';
COMMENT ON COLUMN t_link_0."full_short_url" IS '完整短链接';
COMMENT ON COLUMN t_link_0."origin_url" IS '原始链接';
COMMENT ON COLUMN t_link_0."click_num" IS '点击量';
COMMENT ON COLUMN t_link_0."gid" IS '分组标识';
COMMENT ON COLUMN t_link_0."favicon" IS '网站图标';
COMMENT ON COLUMN t_link_0."enable_status" IS '启用标识 0：启用 1：未启用';
COMMENT ON COLUMN t_link_0."created_type" IS '创建类型 0：接口创建 1：控制台创建';
COMMENT ON COLUMN t_link_0."valid_date_type" IS '有效期类型 0：永久有效 1：自定义';
COMMENT ON COLUMN t_link_0."valid_date" IS '有效期';
COMMENT ON COLUMN t_link_0."describe" IS '描述';
COMMENT ON COLUMN t_link_0."total_pv" IS '历史PV';
COMMENT ON COLUMN t_link_0."total_uv" IS '历史UV';
COMMENT ON COLUMN t_link_0."total_uip" IS '历史UIP';
COMMENT ON COLUMN t_link_0."create_time" IS '创建时间';
COMMENT ON COLUMN t_link_0."update_time" IS '修改时间';
COMMENT ON COLUMN t_link_0."del_time" IS '删除时间戳';
COMMENT ON COLUMN t_link_0."del_flag" IS '删除标识 0：未删除 1：已删除';

CREATE TABLE t_link_access_logs (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "full_short_url" varchar(128),
    "user" varchar(64),
    "ip" varchar(64),
    "browser" varchar(64),
    "os" varchar(64),
    "network" varchar(64),
    "device" varchar(64),
    "locale" varchar(256),
    "first_flag" boolean DEFAULT false,
    "message_id" varchar(64) UNIQUE,
    "create_time" timestamptz,
    "update_time" timestamptz,
    "del_flag" smallint
);

COMMENT ON COLUMN t_link_access_logs."id" IS 'ID';
COMMENT ON COLUMN t_link_access_logs."full_short_url" IS '完整短链接';
COMMENT ON COLUMN t_link_access_logs."user" IS '用户信息';
COMMENT ON COLUMN t_link_access_logs."ip" IS 'IP';
COMMENT ON COLUMN t_link_access_logs."browser" IS '浏览器';
COMMENT ON COLUMN t_link_access_logs."os" IS '操作系统';
COMMENT ON COLUMN t_link_access_logs."network" IS '访问网络';
COMMENT ON COLUMN t_link_access_logs."device" IS '访问设备';
COMMENT ON COLUMN t_link_access_logs."locale" IS '地区';
COMMENT ON COLUMN t_link_access_logs."first_flag" IS '首访标记，true 表示首次访问，false 表示非首次访问';
COMMENT ON COLUMN t_link_access_logs."message_id" IS '消息ID（Redis Stream RecordId，用于幂等）';
COMMENT ON COLUMN t_link_access_logs."create_time" IS '创建时间';
COMMENT ON COLUMN t_link_access_logs."update_time" IS '修改时间';
COMMENT ON COLUMN t_link_access_logs."del_flag" IS '删除标识 0：未删除 1：已删除';

CREATE INDEX t_link_access_logs_idx_full_short_url_user ON t_link_access_logs ("full_short_url", "user");

