CREATE TABLE t_api_token (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "username" varchar(64) NOT NULL,
    "token_hash" char(64) NOT NULL UNIQUE,
    "token_last4" varchar(8) NOT NULL,
    "name" varchar(128) NOT NULL DEFAULT '',
    "enable_status" smallint NOT NULL DEFAULT 0,
    "valid_date" timestamptz,
    "describe" varchar(255),
    "create_time" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "del_flag" smallint NOT NULL DEFAULT 0
);

COMMENT ON COLUMN t_api_token."id" IS 'ID';
COMMENT ON COLUMN t_api_token."username" IS '所属用户名';
COMMENT ON COLUMN t_api_token."token_hash" IS 'token 的 SHA-256 十六进制';
COMMENT ON COLUMN t_api_token."token_last4" IS 'token 后四位';
COMMENT ON COLUMN t_api_token."name" IS '令牌名称';
COMMENT ON COLUMN t_api_token."enable_status" IS '0 启用, 1 禁用';
COMMENT ON COLUMN t_api_token."valid_date" IS '过期时间，NULL 表示不过期';
COMMENT ON COLUMN t_api_token."describe" IS '备注';
COMMENT ON COLUMN t_api_token."create_time" IS '创建时间';
COMMENT ON COLUMN t_api_token."update_time" IS '更新时间';
COMMENT ON COLUMN t_api_token."del_flag" IS '删除标识 0未删 1已删';

CREATE INDEX t_api_token_idx_username ON t_api_token ("username");

-- 首次访问判重表：用于替代 SELECT FOR UPDATE，提升并发性能
CREATE TABLE t_link_first_visit (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "full_short_url" varchar(128) NOT NULL,
    "user" varchar(64) NOT NULL,
    "create_time" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT t_link_first_visit_uniq_url_user UNIQUE ("full_short_url", "user")
);

COMMENT ON COLUMN t_link_first_visit."id" IS 'ID';
COMMENT ON COLUMN t_link_first_visit."full_short_url" IS '完整短链接';
COMMENT ON COLUMN t_link_first_visit."user" IS '用户标识';
COMMENT ON COLUMN t_link_first_visit."create_time" IS '首次访问时间';

CREATE INDEX t_link_first_visit_idx_create_time ON t_link_first_visit ("create_time");

CREATE TABLE t_ai_session (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "session_id" varchar(36) NOT NULL UNIQUE,
    "username" varchar(256) NOT NULL,
    "title" varchar(100) NOT NULL DEFAULT '新对话',
    "create_time" timestamptz,
    "update_time" timestamptz,
    "del_flag" smallint DEFAULT 0
);

COMMENT ON COLUMN t_ai_session."id" IS 'ID';
COMMENT ON COLUMN t_ai_session."session_id" IS 'UUID 会话标识（前端生成）';
COMMENT ON COLUMN t_ai_session."username" IS '所属用户名';
COMMENT ON COLUMN t_ai_session."title" IS '会话标题（首条用户消息截断30字）';
COMMENT ON COLUMN t_ai_session."create_time" IS '创建时间';
COMMENT ON COLUMN t_ai_session."update_time" IS '更新时间';
COMMENT ON COLUMN t_ai_session."del_flag" IS '删除标识 0：未删除 1：已删除';

CREATE INDEX t_ai_session_idx_username ON t_ai_session ("username");

CREATE TABLE t_ai_message (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "session_id" varchar(36) NOT NULL,
    "role" varchar(16) NOT NULL,
    "content" text NOT NULL,
    "create_time" timestamptz,
    "update_time" timestamptz,
    "del_flag" smallint DEFAULT 0
);

COMMENT ON COLUMN t_ai_message."id" IS 'ID';
COMMENT ON COLUMN t_ai_message."session_id" IS '所属会话 UUID';
COMMENT ON COLUMN t_ai_message."role" IS '角色: user / assistant';
COMMENT ON COLUMN t_ai_message."content" IS '消息文本内容';
COMMENT ON COLUMN t_ai_message."create_time" IS '创建时间';
COMMENT ON COLUMN t_ai_message."update_time" IS '更新时间';
COMMENT ON COLUMN t_ai_message."del_flag" IS '删除标识 0：未删除 1：已删除';

CREATE INDEX t_ai_message_idx_session_id ON t_ai_message ("session_id");

-- 创建其余分表，复制模板表的列、索引、约束和字段注释。
DO $$
BEGIN
    FOR shard IN 1..15 LOOP
        EXECUTE format('CREATE TABLE %I (LIKE t_group_0 INCLUDING ALL)', 't_group_' || shard);
        EXECUTE format('CREATE TABLE %I (LIKE t_link_0 INCLUDING ALL)', 't_link_' || shard);
        EXECUTE format('CREATE TABLE %I (LIKE t_link_goto_0 INCLUDING ALL)', 't_link_goto_' || shard);
    END LOOP;
END;
$$;

COMMIT;
